<script setup lang="ts">
import {computed,ref,watch,onDeactivated} from 'vue';
import type {Game,Action} from '../../src/full/types.ts';
import * as C from '../../src/full/content.ts';
import type {Activity,CraftPlan,ForgePlan} from '../../src/full/activity.ts';
import type {TrackingTarget} from '../../src/full/goals.ts';
import {pageSlice} from './play-flow';
import AssetImage from './AssetImage.vue';
import AlchemyWorkshop from './AlchemyWorkshop.vue';
import RelicAtelier from './RelicAtelier.vue';
type Limits={stoneBudget:number;stoneReserve:number;monthBudget:number;remainingMonthsReserve:number;itemReserves:Record<string,number>};
const props=defineProps<{game:Game;mode:'craft'|'forge';busy:boolean;available:boolean;running:boolean;highlight:string;savedPlan:CraftPlan|ForgePlan|null;activity:Activity|null;runtime:{id:string;generation:number;totalMs:number;remainingMs:number;phase:string}|null;embedded?:boolean;minimal?:boolean;consumption:(action:Action)=>string}>();
const emit=defineEmits<{start:[CraftPlan|ForgePlan];track:[TrackingTarget];act:[Action];travel:[CraftPlan|ForgePlan]}>();
const limitsEdited=ref(false),workshop=ref<InstanceType<typeof AlchemyWorkshop>>();let back=false;
const selected=ref(''),page=ref(0),future=ref(false),cycles=ref<number|'target'>(5),targetQuantity=ref(1),targetCycles=ref(50),dialog=ref<HTMLDialogElement>();
const copy=(l:Limits):Limits=>({stoneBudget:l.stoneBudget,stoneReserve:l.stoneReserve,monthBudget:l.monthBudget,remainingMonthsReserve:l.remainingMonthsReserve,itemReserves:{...l.itemReserves}});
const limits=ref<Limits>({stoneBudget:0,stoneReserve:0,monthBudget:0,remainingMonthsReserve:1,itemReserves:{}}),draft=ref<Limits>(copy(limits.value));
const rows=computed(()=>props.mode==='craft'?Object.entries(C.recipes).filter(([,r])=>future.value||C.rank(r.min)<=C.rank(props.game.core.player.realm)).map(([id,r])=>({id,name:r.name,icon:r.output,min:r.min})):Object.entries(C.relics).filter(([id])=>future.value||props.game.ownedRelics.includes(id)||C.rank(props.game.core.player.realm)>=C.rank('golden')).map(([id,r])=>({id,name:r.name,icon:id,min:'golden' as C.RealmId})));
const paged=computed(()=>pageSlice(rows.value,page.value,4));
const recipe=computed(()=>props.mode==='craft'?C.recipes[selected.value]:null),relic=computed(()=>props.mode==='forge'?C.relics[selected.value]:null);
const unit=computed(()=>recipe.value?{stones:recipe.value.stones,months:recipe.value.months,items:recipe.value.inputs}:relic.value?{stones:relic.value.stones,months:C.actionDurations.forge,items:relic.value.inputs}:null);
const output=computed(()=>recipe.value?C.items[recipe.value.output]:null),owned=computed(()=>props.mode==='forge'&&props.game.ownedRelics.includes(selected.value));
const plan=computed<CraftPlan|ForgePlan>(()=>props.mode==='craft'?{kind:'craft',recipeId:selected.value,maxCycles:cycles.value==='target'?targetCycles.value:cycles.value,until:cycles.value==='target'?'target':'cycles',targetQuantity:cycles.value==='target'?targetQuantity.value:null,...copy(limits.value)}:{kind:'forge',relicId:selected.value,maxCycles:1,...copy(limits.value)});
function resetLimits(n:number){if(!unit.value)return;limits.value={stoneBudget:unit.value.stones*n,stoneReserve:0,monthBudget:unit.value.months*n,remainingMonthsReserve:1,itemReserves:{}};}
function restorePlan(){const p=props.savedPlan;if(!p||p.kind!==props.mode||(p.kind==='craft'?p.recipeId:p.relicId)!==selected.value)return;limits.value=copy(p);limitsEdited.value=true;if(p.kind==='craft'){cycles.value=p.until==='target'?'target':p.maxCycles;targetCycles.value=p.maxCycles;targetQuantity.value=p.targetQuantity??1;}}
function select(id:string){if(id===selected.value)return;limitsEdited.value=false;selected.value=id;cycles.value=output.value?.kind==='breakthrough'?'target':5;targetQuantity.value=1;targetCycles.value=50;resetLimits(props.mode==='forge'||cycles.value==='target'?1:5);restorePlan();}
function locate(){const prefix=props.mode==='craft'?'craft-':props.highlight.startsWith('equip-relic-')?'equip-relic-':'forge-',id=props.highlight.startsWith(prefix)?props.highlight.slice(prefix.length):'';if((props.mode==='craft'?C.recipes:C.relics)[id]){future.value=true;page.value=Math.max(0,Math.floor(rows.value.findIndex(r=>r.id===id)/4));select(id);}else if(!rows.value.some(r=>r.id===selected.value)&&rows.value.length)select(rows.value[0].id);}
watch([()=>props.game.core.runId,()=>props.mode,()=>props.highlight],locate,{immediate:true});watch(()=>props.savedPlan,restorePlan);function changeFuture(){page.value=0;if(!rows.value.some(r=>r.id===selected.value)){selected.value='';if(rows.value.length)select(rows.value[0].id);}}
function changeCycles(){if(!recipe.value||limitsEdited.value)return;const n=cycles.value==='target'?Math.min(targetCycles.value,Math.max(1,targetQuantity.value-props.game.core.inventory[recipe.value.output])):cycles.value;resetLimits(n);}
function openLimits(returnView:unknown=false){back=returnView===true;draft.value={...copy(limits.value),itemReserves:Object.fromEntries(Object.keys(unit.value?.items??{}).map(id=>[id,limits.value.itemReserves[id]??0]))};dialog.value?.showModal();}
function closeLimits(){dialog.value?.close();if(back){back=false;workshop.value?.open();}}
function applyLimits(){limits.value=copy(draft.value);limitsEdited.value=true;closeLimits();}
function need(id:string){if(!unit.value)return 1;const n=props.mode==='forge'?1:cycles.value==='target'?Math.min(targetCycles.value,Math.max(0,targetQuantity.value-(recipe.value?props.game.core.inventory[recipe.value.output]:0))):cycles.value;return Math.min(C.maxQuantity,Math.max(1,unit.value.items[id]*n+(limits.value.itemReserves[id]??0)));}
const consumptionWarning=computed(()=>selected.value&&!owned.value?props.consumption(props.mode==='craft'?{type:'CRAFT',recipeId:selected.value}:{type:'FORGE',relic:selected.value}):'');
onDeactivated(()=>dialog.value?.close());
</script>
<template>
 <section class="production-planner" :data-mode="mode" :class="{'paper':!embedded,'play-catalogue':!embedded,'production-minimal':minimal,'alchemy-planner':mode==='craft'&&recipe}" :data-testid="mode==='craft'?'recipe-catalogue':'forging-planner'" tabindex="-1">
  <AlchemyWorkshop ref="workshop" v-if="mode==='craft'&&recipe&&plan.kind==='craft'" :game="game" :plan="plan" :activity="activity" :runtime="runtime" :busy="busy" :available="available" :running="running" :rows="paged.rows" :catalogue="paged" :future="future" :consumption-warning="consumptionWarning" @select="select" @page="page=$event" @future="future=$event;changeFuture()" @material="id=>emit('track',{kind:'item',id,quantity:need(id)})" @start="emit('start',plan)" @travel="emit('travel',plan)" @limits="openLimits" @source="emit('track',{kind:'item',id:recipe.output,quantity:Number.isSafeInteger(targetQuantity)&&targetQuantity>0?targetQuantity:1})">
   <template #settings><details open class="production-intent-disclosure"><summary data-testid="production-intent-toggle">{{cycles==='target'?'目标库存 '+targetQuantity+' · 最多'+targetCycles+'炉':cycles+'炉后停'}} · 调整炉次</summary><div class="production-intent"><label>炉次 <select v-model="cycles" @change="changeCycles" aria-label="炼丹炉次"><option v-for="n in [1,5,20,50]" :key="n" :value="n">{{n}} 炉后停</option><option v-if="cycles!=='target'&&![1,5,20,50].includes(cycles)" :value="cycles">{{cycles}} 炉后停</option><option value="target">库存达到目标即停</option></select></label><template v-if="cycles==='target'"><label>成品库存 <input v-model.number="targetQuantity" @change="changeCycles" type="number" min="1" :max="C.maxQuantity" aria-label="成品目标库存"></label><label>最多 <input v-model.number="targetCycles" @change="changeCycles" type="number" min="1" max="50" aria-label="目标最多炉次">炉</label></template></div></details></template>
  </AlchemyWorkshop>
  <RelicAtelier v-else-if="mode==='forge'&&plan.kind==='forge'" :game="game" :plan="plan" :rows="paged.rows" :catalogue="paged" :future="future" :busy="busy" :available="available" :running="running" :consumption-warning="consumptionWarning" @select="select" @page="page=$event" @future="future=$event;changeFuture()" @material="id=>emit('track',{kind:'item',id,quantity:need(id)})" @limits="openLimits()" @start="emit('start',plan)" @travel="emit('travel',plan)" @equip="emit('act',{type:'EQUIP_RELIC',relic:selected})"/>
  <div v-else class="catalogue-empty production-locked" data-testid="forge-locked"><AssetImage path="art/v2/workshop/furnace-v1.webp" asset-id="production-furnace" fit="contain" aria-hidden="true"/><div><small>当前{{C.realms[game.core.player.realm].name}} · 炉火未启</small><strong>引气入体后可炼丹</strong><p>可先翻阅目录，查看不会启炉或消耗物资。</p><button @click="future=true;changeFuture()">查看完整目录</button></div></div>
  <dialog @close="back&&(back=false,workshop?.open())" ref="dialog" class="production-limit-dialog" aria-labelledby="production-limits-title"><h3 id="production-limits-title">这段{{mode==='craft'?'炼丹':'炼器'}}的投入限额</h3><p>只调整待确认安排，点击开始后才保存；材料保留量不会被下一炉消耗。</p><div class="production-limit-fields"><label>累计灵石预算<input v-model.number="draft.stoneBudget" type="number" min="0" aria-label="累计生产灵石预算"></label><label>灵石至少保留<input v-model.number="draft.stoneReserve" type="number" min="0" aria-label="生产灵石保留量"></label><label>累计游戏月预算<input v-model.number="draft.monthBudget" type="number" min="0" aria-label="累计生产游戏月预算"></label><label>余寿至少保留<input v-model.number="draft.remainingMonthsReserve" type="number" min="1" aria-label="生产余寿保留量"></label><label v-for="(_,id) in unit?.items??{}" :key="id">{{C.items[id].name}}保留<input v-model.number="draft.itemReserves[id]" type="number" min="0" :max="C.maxQuantity" :aria-label="C.items[id].name+'保留量'"/></label></div><footer><button @click="closeLimits">取消调整</button><button class="primary" data-testid="production-apply-limits" @click="applyLimits">应用这些限额</button></footer></dialog>
 </section>
</template>
